def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    if n < 0 or m < 0:
        return 0
    if m == 0 or not items:
        return 0
    dp = [0] * (n + 1)
    for price, value in items:
        if price < 0 or value < 0:
            continue
        for j in range(n, price - 1, -1):
            new_value = dp[j - price] + value
            if new_value > dp[j]:
                dp[j] = new_value
    return dp[n]

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    if n < 0:
        raise ValueError("Degree n must be non-negative")
    if len(coeffs) != n + 1:
        raise ValueError("Length of coeffs must be n + 1")

    terms = []
    for i, coeff in enumerate(coeffs):
        if coeff == 0:
            continue
        degree = n - i
        abs_coeff = abs(coeff)

        # Determine the coefficient part
        if degree > 0 and abs_coeff == 1:
            coeff_str = ""
        else:
            coeff_str = str(abs_coeff)

        # Determine the variable part
        if degree == 0:
            var_str = ""
        elif degree == 1:
            var_str = "x"
        else:
            var_str = f"x^{degree}"

        term = coeff_str + var_str
        terms.append((coeff, term))

    if not terms:
        return "0"

    result = ""
    for idx, (coeff, term) in enumerate(terms):
        if idx == 0:
            if coeff < 0:
                result += "-" + term
            else:
                result += term
        else:
            if coeff < 0:
                result += "-" + term
            else:
                result += "+" + term

    return result

def select_volunteers(n: int, m: int, applicants: List[Tuple[int, int]]) -> Tuple[int, List[Tuple[int, int]]]:
    # Sort applicants by score descending, then by registration number ascending
    from typing import List, Tuple
    sorted_applicants = sorted(applicants, key=lambda x: (-x[1], x[0]))

    # Calculate the cutoff index: 150% of m, rounded down
    cutoff_index = int(m * 1.5)

    # If cutoff_index is 0, no one qualifies? But let's handle edge cases
    if cutoff_index == 0:
        # If m is 0, then cutoff_index is 0, so no one qualifies
        return (0, [])

    # The cutoff score is the score of the applicant at position cutoff_index - 1 (0-indexed)
    # But we need to include all applicants with score >= cutoff_score
    if cutoff_index > len(sorted_applicants):
        cutoff_index = len(sorted_applicants)

    if cutoff_index == 0:
        cutoff_score = 0
    else:
        cutoff_score = sorted_applicants[cutoff_index - 1][1]

    # Collect all applicants with score >= cutoff_score
    qualified = []
    for applicant in sorted_applicants:
        if applicant[1] >= cutoff_score:
            qualified.append(applicant)
        else:
            # Since sorted by score descending, once we find one below cutoff, we can break
            break

    return (cutoff_score, qualified)

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for enc_char, orig_char in zip(encoded, original):
        if enc_char in mapping:
            if mapping[enc_char] != orig_char:
                return "Failed"
        else:
            mapping[enc_char] = orig_char

    if len(mapping) != 26:
        return "Failed"

    decoded = []
    for char in message:
        if char in mapping:
            decoded.append(mapping[char])
        else:
            return "Failed"

    return ''.join(decoded)

def largest_prime_factor(n: int) -> int:
    if n <= 1:
        raise ValueError("Input must be a positive integer greater than 1")

    # Check for factor 2
    if n % 2 == 0:
        return n // 2

    # Check odd factors starting from 3
    i = 3
    while i * i <= n:
        if n % i == 0:
            return n // i
        i += 2

    # If no factor found, n is prime
    return n

