def min_groups(w, n, prices):
    if n == 0:
        return 0
    if len(prices) != n:
        raise ValueError("Length of prices must match n")
    prices_sorted = sorted(prices)
    left = 0
    right = n - 1
    groups = 0
    while left <= right:
        if left == right:
            groups += 1
            break
        if prices_sorted[left] + prices_sorted[right] <= w:
            left += 1
        right -= 1
        groups += 1
    return groups

